# Proposed rule: replace all non-zero cells with max non-zero value
def transform(grid):
    if not grid or not grid[0]:
        return grid
    non_zero = [c for row in grid for c in row if c > 0]
    if not non_zero:
        return grid
    max_val = max(non_zero)
    return [[max_val if cell > 0 else 0 for cell in row] for row in grid]

