from collections import deque

def get_neighbors(r, c, h, w):
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < h and 0 <= nc < w:
            yield (nr, nc)

def count_connected_components(grid, start_val):
    h, w = len(grid), len(grid[0])
    visited = set()
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] == start_val and (r, c) not in visited:
                component = []
                queue = deque([(r, c)])
                visited.add((r, c))
                while queue:
                    cr, cc = queue.popleft()
                    component.append((cr, cc))
                    for nr, nc in get_neighbors(cr, cc, h, w):
                        if grid[nr][nc] == start_val and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            queue.append((nr, nc))
                components.append(component)
    return components

