def get_color_objects(grid):
    """Returns list of (color, min_row, count) for each connected component"""
    from collections import deque

    visited = set()
    objects = []

    def get_neighbors(r, c, h, w):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                yield (nr, nc)

