                while queue:
                    cr, cc = queue.popleft()
                    if (cr, cc) not in visited:
                        visited.add((cr, cc))
                        component_cells.append((cr, cc))
                        for nr, nc in get_neighbors(cr, cc, len(grid), len(grid[0])):
