# Find object with largest vertical span (max_row - min_row)
def find_object_by_span(grid):
    from collections import deque

    visited = set()
    best_color = None
    best_span = -1
    best_max_r = float('-inf')

    def get_neighbors(r, c, h, w):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                yield (nr, nc)

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] > 0 and (r, c) not in visited:
                color = grid[r][c]
                component_cells = []
                queue = deque([(r, c)])
                while queue:
                    cr, cc = queue.popleft()
                    if (cr, cc) not in visited:
                        visited.add((cr, cc))
                        component_cells.append((cr, cc))
                        for nr, nc in get_neighbors(cr, cc, len(grid), len(grid[0])):
                            if grid[nr][nc] == color and (nr, nc) not in visited:
                                queue.append((nr, nc))

                min_r = min(p[0] for p in component_cells)
                max_r = max(p[0] for p in component_cells)
                span = max_r - min_r

                # Prefer larger span, break ties by lower value
                if span > best_span or (span == best_span and color < best_color):
                    best_span = span
                    best_color = color
                    best_max_r = max_r

    return best_color

