from collections import deque

def analyze_components(grid):
    visited = set()
    objects = []

    def get_neighbors(r, c, h, w):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                yield (nr, nc)

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] > 0 and (r, c) not in visited:
                color = grid[r][c]
                component_cells = []
                queue = deque([(r, c)])
                while queue:
                    cr, cc = queue.popleft()
                    if (cr, cc) not in visited:
                        visited.add((cr, cc))
                        component_cells.append((cr, cc))
                        for nr, nc in get_neighbors(cr, cc, len(grid), len(grid[0])):
                            if grid[nr][nc] == color and (nr, nc) not in visited:
                                queue.append((nr, nc))

                min_r = min(p[0] for p in component_cells)
                max_r = max(p[0] for p in component_cells)
                objects.append({'color': color, 'min_r': min_r, 'max_r': max_r, 'count': len(component_cells)})

    # Sort by max_r descending (later extending first)
    objects.sort(key=lambda x: (-x['max_r'], x['color']))
