def get_component_cells(grid, start_r, start_c):
    h, w = len(grid), len(grid[0])
    visited = set()
    q = deque([(start_r, start_c)])
    while q:
        r, c = q.popleft()
        if (r, c) in visited: continue
        if 0 <= r < h and 0 <= c < w and grid[r][c] > 0:
            visited.add((r, c))
            q.append((r+1, c))
            q.append((r-1, c))
            q.append((r, c+1))
            q.append((r, c-1))
    return visited

